// Generated by Codex and not thoroughly checked for correctness.
func TestBodyLimitRejectsOversizedStreamsBeforeHandlers(t *testing.T) {
	gin.SetMode(gin.TestMode)
	for _, testCase := range []struct {
		name          string
		length        int
		contentLength int64
		want          int
	}{
		{"small JSON is preserved", 32, 32, http.StatusOK},
		{"exact cap is accepted", limits.RequestBodyBytes, limits.RequestBodyBytes, http.StatusOK},
		{"one byte above cap is rejected", limits.RequestBodyBytes + 1, limits.RequestBodyBytes + 1, http.StatusRequestEntityTooLarge},
		{"chunked oversized body is rejected", limits.RequestBodyBytes + 1, -1, http.StatusRequestEntityTooLarge},
		{"false short content length does not bypass cap", limits.RequestBodyBytes + 1, 0, http.StatusRequestEntityTooLarge},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			called := false
			router := gin.New()
			router.Use(middlewares.LimitRequestBody)
			router.POST("/body", func(ctx *gin.Context) {
				called = true
				var payload struct {
					Name string `json:"name"`
				}
				if err := ctx.ShouldBindJSON(&payload); err != nil {
					t.Fatal(err)
				}
				if payload.Name != "test" {
					t.Fatal("request body changed")
				}
				ctx.Status(http.StatusOK)
			})
			// An otherwise valid JSON value followed by excessive whitespace must fail.
			body := `{"name":"test"}`
			body += strings.Repeat(" ", testCase.length-len(body))
			request := httptest.NewRequest(http.MethodPost, "/body", strings.NewReader(body))
			request.ContentLength = testCase.contentLength
			response := httptest.NewRecorder()
			router.ServeHTTP(response, request)
			if response.Code != testCase.want || called != (testCase.want == http.StatusOK) {
				t.Fatalf("status=%d called=%v, want status=%d", response.Code, called, testCase.want)
			}
			if !called {
				var payload testutil.APIResponse
				if err := json.Unmarshal(response.Body.Bytes(), &payload); err != nil {
					t.Fatal(err)
				}
				if payload.Error == "" {
					t.Fatal("missing error")
				}
			}
		})
	}
}

// Generated by Codex and not thoroughly checked for correctness.
func TestBodyLimitHandlesMissingAndFailedBodies(t *testing.T) {
	gin.SetMode(gin.TestMode)
	response := httptest.NewRecorder()
	ctx, _ := gin.CreateTestContext(response)
	ctx.Request = &http.Request{}
	middlewares.LimitRequestBody(ctx)
	if ctx.IsAborted() {
		t.Fatal("missing body was rejected")
	}
	body := &mockFailedBody{}
	ctx.Request.Body = body
	middlewares.LimitRequestBody(ctx)
	if !body.closed || response.Code != http.StatusBadRequest || !ctx.IsAborted() {
		t.Fatal("failed body not handled and closed")
	}
}

type mockFailedBody struct{ closed bool }

func (*mockFailedBody) Read([]byte) (int, error) { return 0, errors.New("private transport error") }
func (body *mockFailedBody) Close() error        { body.closed = true; return nil }

var _ io.ReadCloser = (*mockFailedBody)(nil)
